function zigZagOrder(root) {
  const res = [];
  const Q = new Queue();
  Q.push([root, 0]);
  let curLevel = [];
  let curDepth = 0;
  while (!Q.empty()) {
    const [node, depth] = Q.pop();
    if (!node) {
      continue;
    }
    if (depth > curDepth) {
      if (curDepth % 2 === 0) {
        res.push(...curLevel);
      } else {
        res.push(...curLevel.reverse()); // Reverse order
      }
      curLevel = [];
      curDepth = depth;
    }
    curLevel.push(node.val);
    Q.push([node.left, depth + 1]);
    Q.push([node.right, depth + 1]);
  }
  if (curDepth % 2 === 0) {
    // Add the last level
    res.push(...curLevel);
  } else {
    res.push(...curLevel.reverse());
  }
  return res;
}

class QueueNode {
  constructor(val) {
    this.val = val;
    this.next = null;
  }
}

class Queue {
  constructor() {
    this.head = null;
    this.tail = null;
    this._size = 0;
  }

  empty() {
    return !this.head;
  }

  size() {
    return this._size;
  }

  push(val) {
    const newNode = new QueueNode(val);
    if (this.tail) {
      this.tail.next = newNode;
    }

    this.tail = newNode;
    if (!this.head) {
      this.head = newNode;
    }
    this._size++;
  }

  pop() {
    if (this.empty()) {
      throw new Error("empty queue");
    }
    const val = this.head.val;
    this.head = this.head.next;
    if (!this.head) {
      this.tail = null;
    }
    this._size--;
    return val;
  }
}

