class Node {
  public int value;
  public Node left;
  public Node right;

  public Node(int value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }
}

class ZigZagOrder {
  public List<Integer> solve(Node root) {
    if (root == null) {
      return Collections.emptyList();
    }

    List<Integer> res = new ArrayList<>();
    Queue<Map.Entry<Node, Integer>> queue = new LinkedList<>();
    queue.offer(new AbstractMap.SimpleEntry<>(root, 0));
    List<Integer> curLevel = new ArrayList<>();
    int curDepth = 0;

    while (!queue.isEmpty()) {
      Map.Entry<Node, Integer> entry = queue.poll();
      Node node = entry.getKey();
      int depth = entry.getValue();

      if (depth > curDepth) {
        if (curDepth % 2 == 0) {
          res.addAll(curLevel);
        } else {
          Collections.reverse(curLevel);
          res.addAll(curLevel);
        }
        curLevel = new ArrayList<>();
        curDepth = depth;
      }

      curLevel.add(node.value);
      if (node.left != null) {
        queue.offer(new AbstractMap.SimpleEntry<>(node.left, depth + 1));
      }
      if (node.right != null) {
        queue.offer(new AbstractMap.SimpleEntry<>(node.right, depth + 1));
      }
    }

    // Add the last level
    if (curDepth % 2 == 0) {
      res.addAll(curLevel);
    } else {
      Collections.reverse(curLevel);
      res.addAll(curLevel);
    }

    return res;
  }
}

